-- PostgreSQL / Standard SQL Function
CREATE OR REPLACE FUNCTION get_grade(marks NUMERIC)
RETURNS VARCHAR AS $$
BEGIN                                                  -- transaction shuru karo
    IF    marks >= 90 THEN RETURN 'A';
    ELSIF marks >= 75 THEN RETURN 'B';
    ELSIF marks >= 60 THEN RETURN 'C';
    ELSE                   RETURN 'F';
    END IF;
END;
$$ LANGUAGE plpgsql;

-- Use the function
SELECT name, marks, get_grade(marks) AS grade          -- data fetch karo
FROM students;                                         -- kis table se

-- Simple function
CREATE OR REPLACE FUNCTION full_name(first VARCHAR, last VARCHAR)
RETURNS VARCHAR AS $$
    SELECT first || ' ' || last;                       -- data fetch karo
$$ LANGUAGE SQL;

SELECT full_name('Alice', 'Smith');                    -- data fetch karo
